p='person-claims.ts'; s=open(p).read()
a=s.index("/** Whether a claim's status allows"); b=s.index("}\n\n", s.index("function refusal"))+3
s=s[:a]+"""/** Why the server refused an action: the claim's status does not allow it. */
const REFUSALS: Record<ClaimAction, string> = {
  open: 'Only a draft claim can be opened.',
  settle: 'Only an open claim can be settled.',
  void: 'Only a draft or open claim can be voided.',
};

"""+s[b:]
s=s.replace("""    this.claimError.set(null);
    if (!allowed(c, action)) {
      this.claimError.set({ id: c.id, message: refusal(c, action) });
      return;
    }
""","""    this.claimError.set(null);
""")
s=s.replace("refusal(c, action)","REFUSALS[action]")
open(p,'w').write(s)
EOF
grep -n "REFUSALS\|allowed\|refusal" person-claims.ts; cd /home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring && bin/e2e 2>&1 | tail -8

